"""Company home overview, with explicit receipt/selection boundaries."""
HTML='''<section class="card company-data-panel"><div class="company-data-heading"><div><h2>DATOS QUE CONSULTA EIOS</h2><p id="company-data-scope"></p></div><button id="company-data-refresh" type="button">Actualizar estado de datos</button></div><p id="company-data-notice" role="status"></p><div id="company-data-blocks" class="company-data-grid"></div><div id="company-data-parameters"></div><p class="company-data-footnote">Recibido significa guardado para revisión. Seleccionado significa referencia utilizada en el recorrido indicado. Este resumen no confirma que el expediente esté completo ni que una compra o venta sea viable.</p></section>'''
CSS='''
.company-data-heading{display:flex;justify-content:space-between;align-items:start;gap:16px}.company-data-heading button{flex-shrink:0}.company-data-heading p{color:#52647a;line-height:1.5}.company-data-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin:18px 0}.company-data-block{border:1px solid #d3dfed;border-left:4px solid #5686bb;border-radius:8px;padding:18px;background:#f3f7fc;min-width:0}.company-data-block h3{font-size:14px;margin:0 0 12px;color:#13346f}.company-data-block p{font-size:13px;line-height:1.5;color:#52647a}.company-data-badge{display:inline-block;padding:5px 8px;border-radius:5px;background:#dce9fa;font-size:11px;font-weight:700;color:#244e7b}.company-data-STALE,.company-data-RECEIVED_ONLY{border-left-color:#c68b23;background:#fff8e9}.company-data-STALE .company-data-badge,.company-data-RECEIVED_ONLY .company-data-badge{background:#ffedc4;color:#805b0c}.company-data-MISSING{border-left-color:#94a3b8;background:#f5f6f8}.company-data-metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin:14px 0}.company-data-metrics dt{font-size:12px;color:#52647a}.company-data-metrics dd{font-size:23px;font-weight:700;margin:6px 0 0;color:#13346f;font-variant-numeric:tabular-nums}.company-data-files{overflow-wrap:anywhere;font-size:12px}.company-data-files ul{padding-left:18px;line-height:1.7}.company-data-footnote{font-size:13px;color:#52647a;padding-top:12px;border-top:1px solid #dce4ef}@media(max-width:850px){.company-data-grid{grid-template-columns:1fr}.company-data-heading{flex-direction:column}}
'''
JS=r'''
let companyDataReport=null,companyDataSequence=0;
function resetCompanyDataStatus(){companyDataSequence++;companyDataReport=null;$('company-data-blocks').replaceChildren();$('company-data-parameters').replaceChildren();$('company-data-scope').textContent='';$('company-data-notice').textContent='Actualizando las referencias de la empresa seleccionada…'}
function companyDataCard(block){
 const card=document.createElement('article');card.className='company-data-block company-data-'+block.status;const title=document.createElement('h3');title.textContent=block.title;card.append(title);const badge=document.createElement('span');badge.className='company-data-badge';badge.textContent=({BASELINE:'DOCUMENTOS Y REFERENCIAS ORIGINALES',SELECTED:'REFERENCIAS RECIBIDAS SELECCIONADAS',CLEARED:'SELECCIÓN RETIRADA',STALE:'REVISAR ORIGEN',RECEIVED_ONLY:'RECIBIDO · SIN REFERENCIAS SELECCIONADAS',MISSING:'SIN REFERENCIAS EN ESTE BLOQUE',PREPARED:'CONFIGURACIÓN PREPARADA',UNKNOWN:'CONSULTA PENDIENTE'})[block.status]||'REVISAR';card.append(badge);
 const metrics=document.createElement('dl');metrics.className='company-data-metrics';block.metrics.forEach(m=>{const box=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=m.label;dd.textContent=stockNumber(m.value);box.append(dt,dd);metrics.append(box)});card.append(metrics);const description=document.createElement('p');description.textContent=block.description;card.append(description);
 if(block.received_file_count!==undefined){const received=document.createElement('p');received.textContent=stockNumber(block.received_file_count)+' archivos recibidos por carga ordinaria en este bloque; el recuento puede incluir archivos ya seleccionados y no implica uso ni validación.';card.append(received)}
 if(block.source_files?.length){const details=document.createElement('details'),summary=document.createElement('summary'),list=document.createElement('ul');details.className='company-data-files';summary.textContent='Archivos seleccionados consultados ('+stockNumber(block.source_files.length)+')';block.source_files.forEach(name=>{const li=document.createElement('li');li.textContent=name;list.append(li)});details.append(summary,list);card.append(details)}
 const actions=document.createElement('div');actions.className='files-actions';const open=document.createElement('button');open.type='button';open.textContent=({catalogue:'Ver artículos y precios',inventory:'Ver Stock',purchases:'Ver compras',sales:'Ver ventas',parties:'Abrir clientes',finance:'Revisar en propuesta'})[block.key]||'Abrir Parámetros';open.onclick=()=>view(block.destination);actions.append(open);if(block.key==='parties'){const suppliers=document.createElement('button');suppliers.type='button';suppliers.textContent='Abrir proveedores';suppliers.onclick=()=>view('proveedores');actions.append(suppliers)}if(block.destination!=='archivos'){const load=document.createElement('button');load.type='button';load.textContent='Revisar archivos';load.onclick=()=>view('archivos');actions.append(load)}card.append(actions);return card;
}
function renderCompanyDataParameters(){
 const report=companyDataReport;if(!report||report.dataset_id!==$('dataset').value)return;const host=$('company-data-parameters');host.replaceChildren();const p=parametersState,scoped=p?.dataset_id===report.dataset_id&&p?.as_of_date===report.as_of_date&&p?.company_id===report.company_id,values=scoped?p.current.values:{},needed=[['P-MGE-001','margen mínimo'],['P-MGE-002','margen objetivo'],['P-FIN-001','horizonte financiero'],['P-FIN-002','tesorería mínima']],missing=needed.filter(([key])=>values[key]===undefined||values[key]===null||values[key]==='').map(([,name])=>name);
 const block={title:'PARÁMETROS DE LA EMPRESA',status:!scoped?'UNKNOWN':Object.keys(values).length?'PREPARED':'MISSING',metrics:scoped?[{label:'Valores preparados',value:Object.keys(values).length},{label:'Revisión de configuración',value:p.current.revision}]:[],description:!scoped?'Actualiza o abre Parámetros para consultar la configuración de esta empresa.':(missing.length?'Pendientes de preparar: '+missing.join(', ')+'. ':'Los cuatro valores de referencia están preparados. ')+(p.finance_activation?'Hay una activación conservada de horizonte y mínimo para este corte, con sus propios valores. ':'Horizonte y mínimo aún sin activación conservada para este corte. ')+'Preparar parámetros no evalúa operaciones ni conecta por sí solo todos los parámetros al motor.',destination:'parametros'};host.append(companyDataCard(block));
}
function renderCompanyDataStatus(report){
 if(report.dataset_id!==$('dataset').value)return;companyDataReport=report;$('company-data-blocks').replaceChildren();report.blocks.forEach(block=>$('company-data-blocks').append(companyDataCard(block)));$('company-data-scope').textContent=report.legal_name+(report.exclusive_workbook?' · FUENTE EXCLUSIVA: '+report.exclusive_workbook.filename:'')+' · corte '+stockDate(report.as_of_date)+' · '+(report.material_nature==='SYNTHETIC'?'Datos ficticios':report.material_nature==='REAL'?'Datos reales':'Naturaleza sin declarar')+' · '+stockNumber(report.ordinary_received_file_count)+' archivos recibidos por carga ordinaria, incluidos los que ya se hayan seleccionado. El catálogo comercial adicional tiene su incorporación separada.';$('company-data-notice').textContent=report.unclassified_company_file_count?'Hay '+stockNumber(report.unclassified_company_file_count)+' archivos de esta empresa cuya información no permite clasificarlos por corte; no se incluyen en estos recuentos.':'Resumen de referencias al corte. Abre cada apartado para revisar sus datos y limitaciones.';renderCompanyDataParameters();
}
async function refreshCompanyDataStatus(){resetCompanyDataStatus();const sequence=companyDataSequence,dataset=$('dataset').value;if(!dataset)return;try{const report=await api('/api/data-status?dataset='+encodeURIComponent(dataset));if(sequence!==companyDataSequence||dataset!==$('dataset').value)return;renderCompanyDataStatus(report)}catch(e){if(sequence===companyDataSequence)$('company-data-notice').textContent='No se pudo actualizar el estado: '+e.message}}
$('company-data-refresh').onclick=refreshCompanyDataStatus;
'''
